// BALL46 research page: read-only projection of isolated TEST Adaptive research.
const HTML="<!doctype html>\n<html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>Adaptive Over/Under 2.5 Research | BALL46</title>\n<meta name=\"robots\" content=\"noindex,nofollow\">\n<style>\n:root{color-scheme:dark;--bg:#081611;--card:#11271d;--card2:#162e23;--border:#345440;--ink:#edf8f1;--muted:#a4c4b2;--accent:#33d38b;--red:#fa8d87}\n*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:14px/1.6 Inter,system-ui,sans-serif}\na{color:#a9f8c9;text-decoration:none}a:hover{text-decoration:none;color:#fff}\nmain{max-width:1250px;margin:0 auto;padding:28px clamp(14px,3vw,30px) 70px}\nheader{display:flex;gap:15px;align-items:center;flex-wrap:wrap;margin-bottom:24px}\n.brand{font-weight:900;font-size:25px;letter-spacing:-.08em;color:var(--ink)}.brand b{color:var(--accent)}\nnav{margin-left:auto}.tag{border:1px solid var(--border);border-radius:20px;padding:5px 11px;color:#a9e8c3;font-size:11px;letter-spacing:.06em}\nh1{font-size:clamp(23px,3vw,36px);line-height:1.25;margin:9px 0 6px}.muted{color:var(--muted)}.intro{max-width:800px;margin:0 0 25px}\n.panel{background:var(--card);border:1px solid var(--border);border-radius:14px;padding:20px;margin-bottom:18px}\n.panel-title{font-weight:850;font-size:15px;letter-spacing:.02em}.subline{font-size:12px;color:var(--muted);margin-top:4px}\n.summary{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin:18px 0}\n.metric{padding:16px 14px;border-radius:10px;background:var(--card2);border:1px solid var(--border)}\n.metric dt{color:var(--muted);font-size:11px;letter-spacing:.05em;text-transform:uppercase}\n.metric dd{font-size:23px;font-weight:850;margin:4px 0 0;font-variant-numeric:tabular-nums}\n.toolbar{display:flex;flex-wrap:wrap;gap:9px;align-items:center;margin:15px 0 12px}\nselect,button{font:inherit;color:var(--ink);border:1px solid #46725a;border-radius:7px;padding:8px 11px;background:#143022}\nbutton{cursor:pointer;min-width:51px}button[aria-pressed=true]{background:#27734f;border-color:#68d999;color:#fff}\nbutton:focus-visible,select:focus-visible{outline:2px solid var(--accent);outline-offset:3px}\n#equity{width:100%;height:240px;display:block;overflow:visible}\n.line{fill:none;stroke:var(--accent);stroke-width:2;stroke-linecap:round;stroke-linejoin:round;vector-effect:non-scaling-stroke}\n.axis{stroke:#50725d;stroke-width:1;vector-effect:non-scaling-stroke}\n#detail{min-height:23px;margin:8px 0 0;color:var(--muted);font-size:12px}\n.table-wrap{overflow-x:auto;max-height:550px;overflow-y:auto;border:1px solid var(--border);border-radius:10px;margin-top:15px}\ntable{width:100%;border-collapse:collapse;min-width:790px;text-align:left}\nthead{position:sticky;top:0;background:#214633}th,td{padding:11px 12px;border-bottom:1px solid #2f4939;white-space:nowrap;font-variant-numeric:tabular-nums}th{font-size:12px}td{color:#d5ebdf}\n.note{font-size:12px;color:var(--muted);margin-top:18px}.error{color:var(--red)}.positive{color:var(--accent)}.negative{color:var(--red)}\n@media(max-width:650px){main{padding-top:15px}.summary{grid-template-columns:repeat(2,minmax(0,1fr))}.metric dd{font-size:20px}header{gap:8px}.panel{padding:14px}#equity{height:200px}nav{width:100%;margin-left:0}}\n</style></head><body>\n<main>\n<header><a class=\"brand\" href=\"/\">ball<b>46</b></a><span class=\"tag\">READ-ONLY RESEARCH</span><nav><a href=\"/\">Back to BALL46</a></nav></header>\n<h1>ADAPTIVE OVER/UNDER 2.5</h1>\n<p class=\"muted intro\">Research-only performance for 42 experimental formulas. This page shows persisted TEST snapshots. It does not publish picks, start formula runs, place bets, or change BALL46 production statistics.</p>\n<section class=\"panel\" aria-label=\"Research summary\">\n<div class=\"panel-title\">RESEARCH OVERVIEW · 42 FORMULAS</div><div class=\"subline\" id=\"freshness\">Reading the latest verified TEST snapshot…</div>\n<dl class=\"summary\"><div class=\"metric\"><dt>Total observations</dt><dd id=\"count\">—</dd></div><div class=\"metric\"><dt>Settled</dt><dd id=\"settled\">—</dd></div><div class=\"metric\"><dt>Pending</dt><dd id=\"pending\">—</dd></div><div class=\"metric\"><dt>Formulas</dt><dd id=\"formulas\">42</dd></div></dl>\n</section>\n<section class=\"panel\" id=\"equity-panel\" aria-label=\"Per-formula Equity\">\n<div class=\"panel-title\">EQUITY · PERSISTED DAILY SNAPSHOT</div><div class=\"subline\">One formula at a time. Period change updates the existing chart without reloading the table.</div>\n<div class=\"toolbar\"><label for=\"formula\">Formula</label><select id=\"formula\" aria-label=\"Select research formula\"></select><button type=\"button\" data-days=\"7\" aria-pressed=\"false\">7D</button><button type=\"button\" data-days=\"30\" aria-pressed=\"true\">30D</button><button type=\"button\" data-days=\"90\" aria-pressed=\"false\">90D</button></div>\n<svg id=\"equity\" viewBox=\"0 0 720 240\" role=\"img\" aria-label=\"Research equity, 30 days\" preserveAspectRatio=\"none\"><line id=\"zero\" class=\"axis\" x1=\"24\" x2=\"696\" y1=\"207\" y2=\"207\"></line><polyline id=\"curve\" class=\"line\" points=\"\"></polyline></svg>\n<p id=\"detail\" aria-live=\"polite\">Loading saved data…</p>\n</section>\n<section class=\"panel\" aria-label=\"Research formula results\"><div class=\"panel-title\">FORMULA RESULTS · EXPERIMENTAL</div>\n<div class=\"subline\">P/L and ROI shown below are simulated research observations, not the BALL46 production account.</div>\n<div class=\"table-wrap\"><table><thead><tr><th>Formula</th><th>Selection</th><th>Predictions</th><th>Settled</th><th>W / L</th><th>Win rate</th><th>P/L (U)</th><th>ROI</th><th>Max DD (U)</th></tr></thead><tbody id=\"results\"></tbody></table></div>\n</section>\n<p class=\"note\">Research metrics are experimental and may change as settlements are verified. Source: isolated Adaptive O/U TEST snapshots. Production prediction engines, betting ledgers, and published results are not changed by this page.</p>\n</main>\n<script>\n(function(){\n'use strict';\nvar state={data:null,days:30,formula:'A02'};\nvar $=function(id){return document.getElementById(id);};\nvar points=$('curve'),zero=$('zero'),caption=$('detail'),svg=$('equity'),select=$('formula');\nvar buttons=Array.from(document.querySelectorAll('[data-days]'));\nfunction number(v,d){return Number.isFinite(Number(v))?Number(v).toFixed(d):'—';}\nfunction fillRows(formulas){\n var root=$('results'),frag=document.createDocumentFragment();\n for(var i=0;i<formulas.length;i++){\n  var f=formulas[i],tr=document.createElement('tr');\n  var cells=[f.formula,f.selection,f.totalPredictions,f.settled,\n   String(f.win)+' / '+String(f.loss),f.winRate==null?'—':number(f.winRate,1)+'%',\n   number(f.profitLoss,2),f.roi==null?'—':number(f.roi,2)+'%',number(f.maximumDrawdown,2)];\n  for(var j=0;j<cells.length;j++){var td=document.createElement('td');td.textContent=String(cells[j]);if(j===6&&Number(f.profitLoss)<0)td.className='negative';else if(j===6&&Number(f.profitLoss)>0)td.className='positive';tr.appendChild(td)}\n  frag.appendChild(tr);\n }\n root.replaceChildren(frag);\n}\nfunction equity(){\n var data=state.data;if(!data)return;\n var rows=((state.days===90?data.series90:data.series30)||{})[state.formula]||[];\n var all=rows;\n if(state.days===7){\n  var last=rows.length?rows[rows.length-1].date:null;\n  if(last){var day=new Date(last+'T00:00:00Z');day.setUTCDate(day.getUTCDate()-6);var cutoff=day.toISOString().slice(0,10);all=rows.filter(function(row){return row.date>=cutoff;});}\n  else all=[];\n }\n buttons.forEach(function(button){button.setAttribute('aria-pressed',String(Number(button.dataset.days)===state.days));});\n svg.setAttribute('aria-label',state.formula+' research equity, '+state.days+' days');\n if(!all.length){points.setAttribute('points','');zero.setAttribute('y1','207');zero.setAttribute('y2','207');caption.textContent='No persisted daily snapshot for '+state.formula+' in '+state.days+'D';return;}\n // Rebase each selected period to zero, using daily net units recorded in the TEST snapshot.\n var total=0,values=all.map(function(row){total+=Number(row.netUnits)||0;return total;});\n var min=Math.min.apply(null,[0].concat(values)),max=Math.max.apply(null,[0].concat(values)),span=Math.max(1,max-min);\n function y(v){return 207-(v-min)/span*170;}\n var base=y(0);zero.setAttribute('y1',String(base));zero.setAttribute('y2',String(base));\n points.setAttribute('points',values.map(function(v,i){var x=24+(672*i/Math.max(1,values.length-1));return x.toFixed(2)+','+y(v).toFixed(2);}).join(' '));\n caption.textContent=state.formula+' · '+state.days+'D · Period net '+number(total,2)+' units · '+all[0].date+' to '+all[all.length-1].date;\n}\nselect.addEventListener('change',function(){state.formula=select.value;equity();});\nbuttons.forEach(function(button){button.addEventListener('click',function(){state.days=Number(button.dataset.days);equity();});});\nfetch('/research/adaptive-ou/data',{headers:{accept:'application/json'},cache:'no-store'})\n .then(function(response){if(!response.ok)throw new Error('Research data unavailable ('+response.status+')');return response.json();})\n .then(function(data){if(!data.ok||!Array.isArray(data.formulas)||data.formulas.length!==42)throw new Error('Unverified research snapshot');\n  state.data=data;var list=data.formulas;\n  $('count').textContent=String(list.reduce(function(sum,f){return sum+f.totalPredictions;},0));\n  $('settled').textContent=String(list.reduce(function(sum,f){return sum+f.settled;},0));\n  $('pending').textContent=String(list.reduce(function(sum,f){return sum+f.pending;},0));\n  $('freshness').textContent='TEST snapshot · last run '+(data.lastRunAt||'unknown')+' · simulated outcomes only';\n  fillRows(list);var frag=document.createDocumentFragment();\n  list.forEach(function(f){var o=document.createElement('option');o.value=f.formula;o.textContent=f.formula;frag.appendChild(o);});\n  select.appendChild(frag);if(!list.some(function(f){return f.formula===state.formula;}))state.formula=list[0].formula;\n  select.value=state.formula;equity();\n }).catch(function(error){$('freshness').textContent='TEST data temporarily unavailable';caption.className='error';caption.textContent=error.message;});\n})();\n</script></body></html>";
const SOURCE='https://ball46-premium-match-colors-test-20261120.mccarey-supon.workers.dev/__b46_pm_adaptive_research';
const TYPES={'content-type':'application/json; charset=utf-8','cache-control':'public, max-age=0, s-maxage=30','x-content-type-options':'nosniff','x-robots-tag':'noindex, nofollow'};
const maxBytes=2_000_000;
function reject(status,message){return new Response(JSON.stringify({ok:false,error:message}),{status,headers:TYPES});}
function sanitizeNum(value){return typeof value==='number'&&Number.isFinite(value)?value:null;}
function project(source){
 if(source?.code!=='B46_ADAPTIVE_OU_RESEARCH_V1'||!Array.isArray(source.formulas)||source.formulas.length!==42||
   source.series30?.rangeDays!==30||source.series90?.rangeDays!==90)throw Error('Unexpected TEST research schema');
 const formulas=source.formulas.map(f=>{
  if(!/^A\d{2}$/.test(f.formula))throw Error('Invalid formula ID');
  const fields=['historyUsed','totalPredictions','pending','settled','win','loss','winRate','profitLoss','roi','maximumDrawdown'];
  const result={formula:f.formula,selection:String(f.selection||'ALL').slice(0,20)};
  for(const key of fields)result[key]=sanitizeNum(f[key]);
  return result;
 });
 function series(snapshot){
  const projected=Object.create(null);
  for(const f of formulas){
   const rows=snapshot.byFormula?.[f.formula];
   if(!Array.isArray(rows))continue;
   projected[f.formula]=rows.slice(-95).map(row=>{
    if(!/^\d{4}-\d{2}-\d{2}$/.test(row.date))throw Error('Invalid snapshot date');
    return {date:row.date,netUnits:sanitizeNum(row.netUnits)||0,cumulativeUnits:sanitizeNum(row.cumulativeUnits)||0};
   });
  }
  return projected;
 }
 return {ok:true,source:'ADAPTIVE_RESEARCH_TEST_READ_ONLY',formulas,series30:series(source.series30),series90:series(source.series90),lastRunAt:String(source.lastRunAt||'').slice(0,40)};
}
export async function serveAdaptiveReadOnly(request,env,context){
 const {pathname}=new URL(request.url);
 if(!['GET','HEAD'].includes(request.method))return new Response('Method Not Allowed',{status:405,headers:{allow:'GET, HEAD','cache-control':'no-store'}});
 if(pathname==='/research/adaptive-ou'||pathname==='/research/adaptive-ou/'){
  return new Response(request.method==='HEAD'?null:HTML,{headers:{'content-type':'text/html; charset=utf-8','cache-control':'public, max-age=120','x-content-type-options':'nosniff','x-frame-options':'SAMEORIGIN','x-robots-tag':'noindex, nofollow','content-security-policy':"default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; connect-src 'self'; img-src 'self'; base-uri 'none'; form-action 'none'"}});
 }
 if(pathname!=='/research/adaptive-ou/data')return new Response('Not Found',{status:404});
 try{
  if(!env.B46_ADAPTIVE_READ||typeof env.B46_ADAPTIVE_READ.fetch!=='function')throw Error('Research service binding unavailable');
  // Binding calls TEST Worker internally; no Cloudflare credentials exposed to visitors.
  const upstream=await env.B46_ADAPTIVE_READ.fetch(new Request(SOURCE,{headers:{accept:'application/json'},method:'GET',signal:AbortSignal.timeout(18000)}));
  if(!upstream.ok)return reject(503,'Research snapshot not available');
  const len=Number(upstream.headers.get('content-length')||0);
  if(len>maxBytes)return reject(502,'Research response too large');
  const text=await upstream.text();
  if(text.length>maxBytes)return reject(502,'Research response too large');
  const result=project(JSON.parse(text));
  return new Response(request.method==='HEAD'?null:JSON.stringify(result),{headers:TYPES});
 }catch(error){
  console.warn('B46_ADAPTIVE_READONLY_SOURCE_UNAVAILABLE',String(error?.message||error).slice(0,110));
  return reject(503,'Research snapshot temporarily unavailable');
 }
}
